package com.jmadsen.dashhop;
import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
final class WeatherPanel extends LinearLayout implements WeatherRepository.Listener {
 final ShortcutRepository repo;final WeatherRepository weather;String mode="compact";boolean attached;int savedScroll;ScrollView scroll;
 WeatherPanel(Context c,ShortcutRepository r){super(c);repo=r;weather=WeatherRepository.get(c);setOrientation(1);render();}
 int dp(int n){return DockController.px(getContext(),n);}
 TextView text(String value,int size){TextView t=new TextView(getContext());t.setText(value);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setGravity(Gravity.CENTER);t.setPadding(dp(4),dp(4),dp(4),dp(4));return t;}
 TextView action(String value,Runnable r){TextView t=text(value,15);t.setMinHeight(dp(48));t.setOnClickListener(v->r.run());return t;}
 public void changed(){render();}
 void view(String name){if(scroll!=null)scroll.scrollTo(0,0);mode=name;savedScroll=0;render();}
 String time(long stamp,String pattern,String timezone){ZoneId zone;try{zone=ZoneId.of(timezone);}catch(Exception e){zone=ZoneId.systemDefault();}return DateTimeFormatter.ofPattern(pattern,Locale.getDefault()).withZone(zone).format(Instant.ofEpochMilli(stamp));}
 void render(){if(scroll!=null)savedScroll=scroll.getScrollY();removeAllViews();scroll=null;boolean f=repo.str("weatherUnits","f").equals("f");WeatherData d=weather.data;
 LinearLayout toolbar=new LinearLayout(getContext());if(!mode.equals("compact"))toolbar.addView(action("×",()->view("compact")),new LinearLayout.LayoutParams(dp(48),dp(48)));toolbar.addView(action("Refresh",()->weather.refresh(true)),new LinearLayout.LayoutParams(0,dp(48),1));toolbar.addView(action("Setup",()->AppLaunchManager.settings(getContext(),"weather")),new LinearLayout.LayoutParams(0,dp(48),1));addView(toolbar);
 if(weather.phone()){addView(text("Connect / pair phone\nPhone weather is not available yet",16));addView(action("Use direct weather",()->{repo.set("weatherSource","direct");weather.refresh(true);}));return;}
 if(!weather.located()||d==null||!weather.requestKey.equals(weather.key())){addView(text(weather.loading?"Loading weather…":weather.error.isEmpty()?"Set up weather location":weather.error,17));return;}
 boolean stale=d.stale(System.currentTimeMillis())||!weather.error.isEmpty();String freshness=(weather.loading?"Refreshing · ":stale?"Cached / stale · ":"Updated · ")+time(d.fetched,"MMM d h:mm a",ZoneId.systemDefault().getId());
 scroll=new ScrollView(getContext());LinearLayout body=new LinearLayout(getContext());body.setOrientation(1);scroll.addView(body);addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
 if(mode.equals("compact")){LinearLayout summary=new LinearLayout(getContext());summary.setOrientation(1);summary.setGravity(Gravity.CENTER);TextView temperature=text(WeatherData.icon(d.code)+" "+WeatherData.degrees(d.temperature,f),34);temperature.setTextColor(0xff75e1db);summary.addView(temperature);summary.addView(text(d.place+" · "+WeatherData.condition(d.code),16));JSONObject daily=d.json.optJSONObject("daily");double hi=Double.NaN,lo=Double.NaN;if(daily!=null){JSONArray highs=daily.optJSONArray("temperature_2m_max"),lows=daily.optJSONArray("temperature_2m_min");if(highs!=null)hi=highs.optDouble(0,Double.NaN);if(lows!=null)lo=lows.optDouble(0,Double.NaN);}JSONObject current=d.json.optJSONObject("current");double feels=current==null?Double.NaN:current.optDouble("apparent_temperature",Double.NaN),wind=current==null?Double.NaN:current.optDouble("wind_speed_10m",Double.NaN);summary.addView(text("Feels like "+WeatherData.degrees(feels,f)+" · Wind "+(Double.isNaN(wind)?"—":Math.round(f?wind*.621371:wind)+(f?" mph":" km/h")),15));summary.addView(text("High "+WeatherData.degrees(hi,f)+" / Low "+WeatherData.degrees(lo,f),15));summary.setOnClickListener(v->view("hourly"));for(int i=0;i<summary.getChildCount();i++)summary.getChildAt(i).setOnClickListener(v->view("hourly"));body.addView(summary);body.addView(action("Hourly / 7-day forecast",()->view("hourly")));}
 else {LinearLayout tabs=new LinearLayout(getContext());tabs.addView(action("Hourly",()->view("hourly")),new LinearLayout.LayoutParams(0,dp(48),1));tabs.addView(action("7 days",()->view("daily")),new LinearLayout.LayoutParams(0,dp(48),1));body.addView(tabs);try{JSONObject section=d.json.getJSONObject(mode.equals("daily")?"daily":"hourly");JSONArray times=section.getJSONArray("time");int shown=0;for(int i=0;i<times.length();i++){long stamp=WeatherData.time(times.get(i),d.timezone);if(!mode.equals("daily")&&stamp<System.currentTimeMillis()-3600000L)continue;String row=time(stamp,mode.equals("daily")?"EEE, MMM d":"EEE h a",d.timezone);if(mode.equals("daily"))row+="  "+WeatherData.degrees(section.getJSONArray("temperature_2m_max").optDouble(i,Double.NaN),f)+" / "+WeatherData.degrees(section.getJSONArray("temperature_2m_min").optDouble(i,Double.NaN),f);else{row+="  "+WeatherData.degrees(section.getJSONArray("temperature_2m").optDouble(i,Double.NaN),f);JSONArray rain=section.optJSONArray("precipitation_probability");if(rain!=null&&!rain.isNull(i))row+="  Rain "+rain.optInt(i)+"%";}body.addView(text(row,16));if(++shown>=24)break;}}catch(Exception e){body.addView(text("Forecast details unavailable",16));}}
 body.addView(text("Weather alerts: not supplied by this provider",12));body.addView(text(freshness,12));if(!weather.error.isEmpty())body.addView(text(weather.error,13));TextView credit=action("Weather: Open-Meteo · CC BY 4.0",()->{try{getContext().startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://open-meteo.com/")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception ignored){}});credit.setTextSize(12);body.addView(credit);int restore=savedScroll;scroll.post(()->{if(scroll!=null)scroll.scrollTo(0,restore);});
 }
 protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;weather.add(this);}
 protected void onDetachedFromWindow(){weather.remove(this);attached=false;super.onDetachedFromWindow();}
}
